"""Create temporary Vite QA inputs from current canonical Java Markdown."""
from pathlib import Path
import json
import re

root = Path(__file__).resolve().parents[4]
frontend = root / "frontend"
entries = []
for path in sorted((root / "content/java").glob("*/*.md")):
    head, body = path.read_text(encoding="utf-8").split("\n---\n", 1)
    entries.append(dict(key=re.search(r"^contentKey: (.+)$", head, re.M).group(1),
                        title=re.search(r"^title: (.+)$", head, re.M).group(1).strip('"'),
                        body=body, path=path.relative_to(root).as_posix()))
(frontend / "qa-java-final-data.json").write_text(json.dumps(entries, ensure_ascii=False), encoding="utf-8")
(frontend / "qa-java-final.tsx").write_text('import { useState } from \'react\'\nimport { createRoot } from \'react-dom/client\'\nimport { MarkdownContent } from \'./src/components/MarkdownContent\'\nimport data from \'./qa-java-final-data.json\'\nimport \'./src/styles.css\'\nimport \'./src/app-update.css\'\nimport \'./src/search.css\'\nimport \'./src/dashboard.css\'\nimport \'./src/learning.css\'\nimport \'./src/concept.css\'\nimport \'./src/quiz.css\'\nimport \'./src/wrong-note.css\'\nimport \'./src/review.css\'\nimport \'./src/import.css\'\nimport \'./src/learning-detail.css\'\nimport \'./src/concept-reading-guide.css\'\nimport \'./src/quiz-setup-guide.css\'\nimport \'./src/quiz-session-focus.css\'\nimport \'./src/daily-loop-guide.css\'\nimport \'./src/search-guide.css\'\nimport \'./src/learning-content.css\'\nimport \'./src/auth.css\'\nimport \'./src/ui-refresh.css\'\nimport \'./src/foundation.css\'\nimport \'./src/header-search.css\'\nimport \'./src/home.css\'\nimport \'./src/interview-practice.css\'\nimport \'./src/topic-focus.css\'\nimport \'./src/saved-quiz-sets.css\'\nimport \'./src/concept-compare.css\'\nimport \'./src/bookmarks.css\'\nimport \'./src/density.css\'\nimport \'./src/step5-corrections.css\'\nimport \'./src/step6-learning-area.css\'\nimport \'./src/step6-qa-corrections.css\'\nimport \'./src/step7-quiz.css\'\nimport \'./src/step7-result-width.css\'\nimport \'./src/step8-review.css\'\nimport \'./src/step8-wrong-note-alignment.css\'\nimport \'./src/learning-workspace.css\'\nimport \'./src/concept-reader.css\'\nimport \'./src/markdown-renderer.css\'\nimport \'./src/learning-visualization.css\'\nimport \'./src/public-learning.css\'\nfunction QA() {\n const [key, setKey] = useState(data[0].key)\n const entry = data.find(e => e.key === key)!\n return <main style={{maxWidth: 960, margin: \'0 auto\', padding: 20, minWidth: 0}}>\n  <label>검증 Concept <select aria-label="검증 Concept" value={key} onChange={e=>setKey(e.target.value)}>{data.map(e=><option key={e.key} value={e.key}>{e.title}</option>)}</select></label>\n  <label>검증 테마 <select aria-label="검증 테마" defaultValue="light" onChange={e=>{document.documentElement.dataset.theme=e.target.value}}><option value="light">Light</option><option value="dark">Dark</option></select></label>\n  <h1 id="qa-title">{entry.title}</h1><article className="concept-body" key={key}><MarkdownContent>{entry.body}</MarkdownContent></article>\n </main>\n}\ndocument.documentElement.dataset.theme=\'light\'\ncreateRoot(document.getElementById(\'root\')!).render(<QA />)\n', encoding="utf-8")
(frontend / "qa-java-final.html").write_text('<!doctype html><html lang="ko"><head><meta charset="UTF-8"><title>Java 전체 콘텐츠 QA</title><style>select{max-width:100%;display:block}main{box-sizing:border-box}body{margin:0}</style></head><body><div id="root"></div><script type="module" src="/qa-java-final.tsx"></script></body></html>', encoding="utf-8")
print(f"Created QA fixture for {len(entries)} Concepts")
